use super::*;
use crate::schema::scene_preparation::DocumentSceneContent;
use serde_json::Value;
fn rows()->Vec<Value>{serde_json::from_str(include_str!("../../../../🧬️schema/🎬️scene/📋️prepare/🧫️fixtures/🎬️vector/🔣️.json")).unwrap()}
fn install(render:AppRenderOperationContext,read:store::SnapshotRead<DrawingSnapshot>)->(usize,u64){let effects=reconcile_source(render,||Ok(read));match effects.last().unwrap(){Effect::SpawnJob{job,input,..}=>(usize::from(u16::from_le_bytes(input[1..3].try_into().unwrap())),*job),_=>panic!("the production reconciliation must spawn the prepared geometry job")}}

fn drive(job:&mut dyn BoundedJob)->bool{for _ in 0..1000000{match job.step(JobBudget{fuel:1,deadline_ms:8}){JobStep::Running(_)=>{},JobStep::Done(_)=>return true,JobStep::Failed(_)=>return false}}panic!("mounted geometry did not settle")}
async fn source(row:&Value)->store::ArtifactStore<DrawingSnapshot,crate::op::DrawingMutation>{let document:DrawingSnapshot=serde_json::from_value(row["document"].clone()).unwrap();let mut source=store::ArtifactStore::new(store::create_document_envelope::<DrawingSnapshot,crate::op::DrawingMutation>("drawing.drawing","mounted-vector",document,None), protocol::ActorId(protocol::LOCAL_ACTOR_ID.into())).await.unwrap();source.install_document_store_owners_exact(crate::spr::drawing_document_store_owners());source}
fn return_reads(source:&mut store::ArtifactStore<DrawingSnapshot,crate::op::DrawingMutation>){if let Some(mut returned)=source.take_returned_snapshot_read_retirement().unwrap(){for _ in 0..100000{if returned.terminal_is_empty(){return;}returned.close_step(1,4096).unwrap();}panic!("source return did not settle");}}
fn maintenance_exact(instance:u32){let mut owner=GeometryOwner::new(instance);let copy=owner.next_copy_byte_demand().unwrap();let release=owner.next_release_byte_demand().unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:owner.next_capacity_byte_demand(if copy>0{copy}else{release}).unwrap(),maximum_release_bytes:release,maximum_depth:owner.next_depth_demand().unwrap()};owner.close_step(grant).unwrap();}
fn finish(instance:u32,source:&mut store::ArtifactStore<DrawingSnapshot,crate::op::DrawingMutation>){GeometryOwner::new(instance).begin_close().unwrap();for _ in 0..1000000{maintenance_exact(instance);return_reads(source);if terminal_is_empty(instance){break;}}assert!(terminal_is_empty(instance));for _ in 0..100000{if store::SpaceMember::close_owned_terminal_is_empty(source){break;}store::SpaceMember::close_owned_step(source,1,4096).unwrap();}assert!(store::SpaceMember::close_owned_terminal_is_empty(source));}
fn render(source:&store::ArtifactStore<DrawingSnapshot,crate::op::DrawingMutation>,instance:u32,base:u64)->AppRenderOperationContext{AppRenderOperationContext{app_instance_id:instance,base_revision:semio_framework_job::RevisionId(base),generation:semio_framework_job::Generation(source.generation()),canonical_base_revision:source.content_revision()}}
#[semio_framework_async_macros::async_test]
async fn mounted_painted_query_borrows_resolved_source_and_retires_after_real_replacement(){
 use crate::schema::geometry::picking::paint::PaintedPathHitJob;
 let checks:Vec<Value>=serde_json::from_str(include_str!("../../../../🧬️schema/🧮️geometry/🎯️picking/🎨️paint/🧫️fixtures/🎬️resolved/🔣️.json")).unwrap();
 for check in checks{for grant in [1,7,4096]{
  let row=rows().into_iter().find(|row|row["name"]==check["source"]).unwrap();let mut source=source(&row).await;let first=render(&source,710021,u64::from_le_bytes(source.content_revision()[..8].try_into().unwrap()));let captured=identity(first);let read=source.snapshot_read().unwrap();assert!(prepare(first,read.get()));let(slot,id)=install(first,read);let mut worker=factory(id,&input(slot,captured,id),None).unwrap();
  let mut pending=0;loop{let status=with_query(captured,|status,plan|{assert!(plan.is_none(),"waiting must not borrow unfinished producer geometry");status});assert_eq!(status,SceneAdmissionStatus::Pending);pending+=1;match worker.step(JobBudget{fuel:1,deadline_ms:8}){JobStep::Running(_)=>{},JobStep::Done(_)=>break,JobStep::Failed(error)=>panic!("real geometry producer failed: {}",String::from_utf8_lossy(&error))}assert!(pending<1000000);}
  drop(worker);let point=serde_json::from_value(check["point"].clone()).unwrap();let mut query=with_query(captured,|status,plan|{assert_eq!(status,SceneAdmissionStatus::Ready);PaintedPathHitJob::from_prepared(plan.unwrap().scene.plan.nodes.iter().find(|node|node.id=="result").unwrap(),point,0.0,0.001).unwrap()});
  let pointer=with_query(captured,|_,plan|{let DocumentSceneContent::Path{segments,..}=&plan.unwrap().scene.plan.nodes.iter().find(|node|node.id=="result").unwrap().content else{panic!("actual completed paths required")};segments.as_ptr()});
  let mut done=false;for _ in 0..2000000{let p=with_query(captured,|status,plan|{assert_eq!(status,SceneAdmissionStatus::Ready);let DocumentSceneContent::Path{segments,..}=&plan.unwrap().scene.plan.nodes.iter().find(|node|node.id=="result").unwrap().content else{panic!("actual completed paths required")};assert_eq!(segments.as_ptr(),pointer,"every step borrows the genuine completed source");query.advance(grant,|index|segments.get(index).cloned()).unwrap()});if p.done{done=true;break;}}
  assert!(done);assert_eq!(query.result().unwrap().contains,check["expected"].as_bool().unwrap());let(mut retired,output)=query.into_retirement();assert!(output.is_some());while !retired.advance(grant).unwrap().done{}assert!(retired.terminal_is_empty());
  let mut interrupted=with_query(captured,|_,plan|PaintedPathHitJob::from_prepared(plan.unwrap().scene.plan.nodes.iter().find(|node|node.id=="result").unwrap(),point,0.0,0.001).unwrap());let mut child_admitted=false;for _ in 0..65538{let p=with_query(captured,|_,plan|{let DocumentSceneContent::Path{segments,..}=&plan.unwrap().scene.plan.nodes.iter().find(|node|node.id=="result").unwrap().content else{unreachable!()};interrupted.advance(1,|index|segments.get(index).cloned()).unwrap()});assert!(!p.done);if p.phase=="flattening"{child_admitted=true;break;}}assert!(child_admitted,"the interrupted query owns the actual flatten child");
  source.apply_one(source.generation(),crate::mutations::delete_layer("result".into()),store::HistoryLane::Document).await.unwrap();let live=render(&source,first.app_instance_id,u64::from_le_bytes(source.content_revision()[..8].try_into().unwrap()));let read=source.snapshot_read().unwrap();assert!(prepare(live,read.get()));assert_eq!(with_query(captured,|status,plan|{assert!(plan.is_none());status}),SceneAdmissionStatus::Stale);interrupted.cancel();let(mut retired,output)=interrupted.into_retirement();assert!(output.is_none());let mut child_cleanup_work=0;loop{let p=retired.advance(grant).unwrap();child_cleanup_work=p.work;if p.done{break;}}assert!(child_cleanup_work>8,"real child cleanup must advance beyond the parent headers");assert!(retired.terminal_is_empty());let(next,new_id)=install(live,read);let mut replacement=factory(new_id,&input(next,identity(live),new_id),None).unwrap();assert!(drive(replacement.as_mut()));drop(replacement);finish(first.app_instance_id,&mut source);
  eprintln!("[DEBUG] Actual mounted painted query {} grant={grant} producer_waits={pending} matched_source=true real_edit_stale=true actual_child_retirement_work={child_cleanup_work} query_and_source_terminal_empty=true",check["source"]);
 }}
}
#[semio_framework_async_macros::async_test]
async fn mounted_vector_query_borrows_only_exact_complete_geometry_and_refuses_superseded_source(){
 let row=rows().remove(0);let mut source=source(&row).await;let first=render(&source,710011,9007199254740993);let captured=identity(first);let read=source.snapshot_read().unwrap();assert!(prepare(first,read.get()));
 assert_eq!(with_query(captured,|status,plan|{assert!(plan.is_none());status}),SceneAdmissionStatus::Pending);let(slot,job)=install(first,read);let mut worker=factory(job,&input(slot,captured,job),None).unwrap();assert!(drive(worker.as_mut()));drop(worker);
 let pointer=with_visual(Some(first),|plan,_,_|plan.unwrap().plan.nodes.as_ptr());with_query(captured,|status,plan|{assert_eq!(status,SceneAdmissionStatus::Ready);assert_eq!(plan.unwrap().scene.plan.nodes.as_ptr(),pointer,"queries borrow the actual complete visual without a plan clone");});
 let shell=MOUNTED.with(|r|r.borrow().shells[slot].clone());let checked_out=shell.borrow_mut();assert_eq!(with_query(captured,|status,plan|{assert!(plan.is_none());status}),SceneAdmissionStatus::Pending);drop(checked_out);
 let replacement=render(&source,first.app_instance_id,9007199254740992);let read=source.snapshot_read().unwrap();assert!(prepare(replacement,read.get()));assert_eq!(with_query(captured,|status,plan|{assert!(plan.is_none());status}),SceneAdmissionStatus::Stale);assert_eq!(with_query(identity(replacement),|status,plan|{assert!(plan.is_none());status}),SceneAdmissionStatus::Pending);
 let(next,new_job)=install(replacement,read);let mut worker=factory(new_job,&input(next,identity(replacement),new_job),None).unwrap();assert!(drive(worker.as_mut()));drop(worker);with_query(identity(replacement),|status,plan|{assert_eq!(status,SceneAdmissionStatus::Ready);assert!(plan.is_some());});finish(first.app_instance_id,&mut source);assert_eq!(with_query(identity(replacement),|status,plan|{assert!(plan.is_none());status}),SceneAdmissionStatus::Stale);
 eprintln!("[DEBUG] Actual mounted query observed pending work, borrowed the exact complete visual, yielded around a checked-out owner and refused superseded full-width source lanes and a closed instance");
}
#[semio_framework_async_macros::async_test]
async fn mounted_vector_query_preserves_real_failure_after_candidate_retirement_and_recovers_on_new_source(){
 let row=rows().remove(0);let mut source=source(&row).await;let mut failed=render(&source,710012,11);failed.generation.0+=1;let read=source.snapshot_read().unwrap();assert!(prepare(failed,read.get()));let(slot,job)=install(failed,read);let mut worker=factory(job,&input(slot,identity(failed),job),None).unwrap();assert!(!drive(worker.as_mut()));drop(worker);
 assert_eq!(with_query(identity(failed),|status,plan|{assert!(plan.is_none());status}),SceneAdmissionStatus::Failed);
 for _ in 0..100000{maintenance(failed.app_instance_id,1,4096);return_reads(&mut source);if MOUNTED.with(|r|r.borrow().shells[slot].borrow().is_none()){break;}}
 assert!(MOUNTED.with(|r|r.borrow().shells[slot].borrow().is_none()));assert_eq!(with_query(identity(failed),|status,plan|{assert!(plan.is_none());status}),SceneAdmissionStatus::Failed,"cleanup must not turn a failed source into an endless pending query");
 let live=render(&source,failed.app_instance_id,12);let read=source.snapshot_read().unwrap();assert!(prepare(live,read.get()));assert_eq!(with_query(identity(live),|status,plan|{assert!(plan.is_none());status}),SceneAdmissionStatus::Pending);let(slot,job)=install(live,read);let mut worker=factory(job,&input(slot,identity(live),job),None).unwrap();assert!(drive(worker.as_mut()));drop(worker);with_query(identity(live),|status,plan|{assert_eq!(status,SceneAdmissionStatus::Ready);assert!(plan.is_some());});finish(live.app_instance_id,&mut source);
 eprintln!("[DEBUG] Actual producer source refusal persisted through all candidate/source-return cleanup, then a genuinely admitted replacement recovered with complete borrowed geometry");
}
#[semio_framework_async_macros::async_test]
