 for row in rows(){let mut source=source(&row).await;let render=render(&source,700007,11);let read=source.snapshot_read().unwrap();assert!(prepare(render,read.get()));let(slot,job)=install(render,read);assert!(with_visual(Some(render),|plan,_,_|plan.is_none()));let mut worker=factory(job,&input(slot,identity(render),job),None).unwrap();assert!(worker.terminal_drop_is_shallow());assert!(drive(worker.as_mut()));
 with_visual(Some(render),|plan,revision,fresh|{let plan=plan.unwrap();assert!(fresh);assert_eq!(u64::from(revision),job&COUNTER_MAX);assert!(plan.plan.nodes.iter().all(|n|!matches!(n.content,DocumentSceneContent::Boolean{..}|DocumentSceneContent::Trace{..})));let views=crate::schema::scene_view::nodes(&plan.plan,None).unwrap();for view in &views{if let Some(node)=plan.plan.nodes.iter().find(|node|node.id==view.id){if let DocumentSceneContent::Path{segments,..}=&node.content{assert_eq!(view.segments.as_ptr(),segments.as_ptr(),"canvas borrows the actual completed geometry");}}}let tree=super::super::canvas_window::render(Some(plan),revision,&serde_json::from_value(row["document"].clone()).unwrap(),&Default::default(),&Default::default(),"selectDirect",&[],&[]).unwrap();let _=tree;});drop(worker);finish(render.app_instance_id,&mut source);eprintln!("[DEBUG] Mounted vector source {} published complete borrowed canvas geometry and retired its genuine read",row["name"]);
 }
