#[semio_framework_async_macros::async_test]
async fn mounted_vector_geometry_failed_slot_is_not_owned_by_its_previous_instance(){let row=rows().remove(0);let mut source=source(&row).await;let mut first=render(&source,700010,11);first.generation.0+=1;let read=source.snapshot_read().unwrap();assert!(prepare(first,read.get()));let(slot,job)=install(first,read);let mut worker=factory(job,&input(slot,identity(first),job),None).unwrap();assert!(!drive(worker.as_mut()));drop(worker);for _ in 0..1000{maintenance_exact(first.app_instance_id);return_reads(&mut source);let empty=MOUNTED.with(|r|r.borrow().shells[slot].borrow().is_none());if empty{break;}}MOUNTED.with(|r|{let r=r.borrow();assert!(r.shells[slot].borrow().is_none());assert!(r.instances[first.app_instance_id as usize%INSTANCES].unwrap().candidate.is_none(),"a retired failed candidate cannot retain authority over a reusable shell");});let second=render(&source,700011,12);let read=source.snapshot_read().unwrap();assert!(prepare(second,read.get()));let(next,new_job)=install(second,read);assert_eq!(slot,next,"the fixed arena really reused the retired slot");close(first.app_instance_id,1,4096);let mut worker=factory(new_job,&input(next,identity(second),new_job),None).unwrap();assert!(drive(worker.as_mut()),"closing the first instance cannot cancel the reused slot");drop(worker);finish(second.app_instance_id,&mut source);assert!(terminal_is_empty(first.app_instance_id));eprintln!("[DEBUG] Failed mounted candidate relinquished its exact shell before another instance reused it; previous close did not cancel the new owner");}
#[semio_framework_async_macros::async_test]
async fn mounted_vector_geometry_reconciliation_cancels_the_actual_superseded_private_owner(){let row=rows().pop().unwrap();let mut source=source(&row).await;let first=render(&source,700012,11);let read=source.snapshot_read().unwrap();assert!(prepare(first,read.get()));let(slot,job)=install(first,read);let mut old=factory(job,&input(slot,identity(first),job),None).unwrap();old.step(JobBudget{fuel:1,deadline_ms:8});let second=render(&source,first.app_instance_id,12);let read=source.snapshot_read().unwrap();assert!(prepare(second,read.get()));let effects=reconcile_source(second,||Ok(read));assert!(matches!(effects.first(),Some(Effect::CancelJob{job:old_job})if *old_job==job));let Some(Effect::SpawnJob{job,input,..})=effects.last()else{panic!("replacement must spawn after cancellation")};let mut replacement=factory(*job,input,None).unwrap();assert!(!drive(old.as_mut()));assert!(drive(replacement.as_mut()));drop(old);drop(replacement);finish(first.app_instance_id,&mut source);eprintln!("[DEBUG] Production reconciliation emitted actual private cancellation before isolated replacement spawn and retained both real source leases through terminal cleanup");}

