 let pending=render(&source,first.app_instance_id,12);let read=source.snapshot_read().unwrap();assert!(prepare(pending,read.get()));let(slot,pending_job)=install(pending,read);let mut outdated=factory(pending_job,&input(slot,identity(pending),pending_job),None).unwrap();assert!(matches!(outdated.step(JobBudget{fuel:1,deadline_ms:8}),JobStep::Running(_)));
 source.apply_one(source.generation(),crate::mutations::delete_layer(layer.clone()),store::HistoryLane::Document).await.unwrap();let live=render(&source,first.app_instance_id,13);assert_ne!(live.generation,first.generation);assert_ne!(live.canonical_base_revision,first.canonical_base_revision);assert!(!drive(outdated.as_mut()),"an actual document edit invalidates the captured source authority");drop(outdated);
 with_visual(Some(live),|plan,revision,fresh|{assert!(!fresh);assert_eq!(u64::from(revision),job&COUNTER_MAX);assert!(plan.unwrap().plan.nodes.iter().any(|node|node.id==layer),"the last complete picture remains until its replacement is ready");});
 let read=source.snapshot_read().unwrap();assert!(read.get().layers.is_empty());assert!(prepare(live,read.get()));let(slot,new_job)=install(live,read);let mut replacement=factory(new_job,&input(slot,identity(live),new_job),None).unwrap();assert!(drive(replacement.as_mut()));drop(replacement);
